contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 supply, uint256 value) public {
        require(value > 0);
        require(value <= supply * (10 ** uint256(c.decimals())));
        c = new C(supply, "t", "T");
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 tsBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool ok = c.burn(value); if (__ESBMC_reverted()) return;
        assert(ok && c.balanceOf(address(this)) + value == balBefore && c.totalSupply() + value == tsBefore);
    }
    receive() external payable {}
}

