contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 supply, uint256 value) internal {
        vm.assume(value > 0);
        vm.assume(value <= supply * (10 ** uint256(c.decimals())));
        c = new ERCDDAToken(supply, "t", "T");
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 tsBefore;
        try c.totalSupply() returns (uint256 __r) { tsBefore = __r; } catch { return; }
        bool ok;
        try c.burn(value) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(ok && c.balanceOf(address(this)) + value == balBefore && c.totalSupply() + value == tsBefore);
    }

    function testFuzz_run(uint256 supply, uint256 value) public {
        _run(supply, value);
    }

    receive() external payable {}
